function dump(n, depth){
  if(!n) return null;
  const o = {id:n.id, name:n.name, type:n.type, w:n.width, h:n.height};
  if(n.type==="TEXT"){o.chars=n.characters; o.fontName=n.fontName; o.fontSize=n.fontSize; o.fills=JSON.stringify(n.fills);}
  if("cornerRadius" in n) o.cornerRadius=n.cornerRadius;
  if("fills" in n && n.type!=="TEXT") o.fills=JSON.stringify(n.fills);
  if("strokes" in n) o.strokes=JSON.stringify(n.strokes);
  if("layoutMode" in n && n.layoutMode!=="NONE"){o.layoutMode=n.layoutMode;o.padding=[n.paddingTop,n.paddingRight,n.paddingBottom,n.paddingLeft];o.itemSpacing=n.itemSpacing;}
  if(depth>0 && "children" in n) o.children=n.children.map(c=>dump(c,depth-1));
  return o;
}
