const home=await figma.getNodeByIdAsync("51:85");
const fixed=[];
for(const w of home.children){
 if(w.name.endsWith("Section")){
   w.counterAxisSizingMode="AUTO";
   for(const ch of w.children){
     if(ch.layoutMode==="VERTICAL"&&ch.name!=="Hero"){ch.primaryAxisSizingMode="AUTO";}
     // nested rows/cols inside sections
     const nested=ch.findAll(n=>n.layoutMode==="VERTICAL"||n.layoutMode==="HORIZONTAL");
     for(const n of nested){
       if(n.layoutMode==="VERTICAL"&&n.primaryAxisSizingMode==="FIXED"&&n.name!=="Image"&&n.name!=="MainImage")n.primaryAxisSizingMode="AUTO";
       if(n.layoutMode==="HORIZONTAL"&&n.counterAxisSizingMode==="FIXED"&&n.name!=="Image"&&n.name!=="MainImage")n.counterAxisSizingMode="AUTO";
     }
   }
   fixed.push(w.name+"="+Math.round(w.height));
 }
}
return JSON.stringify({fixed,totalH:Math.round(home.height)});

